 5	\begin{theorem}\label{thm:commutativity-points}
 6	Let $(\psi, A, B, L)$ be an $(\eps, \delta, \gamma)$-good symmetric strategy for the
 7	$(m,q,d)$ low individual degree test.
 8	On average over independent and uniformly random $\bu, \bv \sim \F_q^m$,
 9	\begin{equation*}
10	(A^{u}_a \cdot A^{v}_b) \otimes I \approx_{32\gamma m} (A^{v}_b\cdot A^{u}_a) \otimes I.
11	\end{equation*}
12	\end{theorem}
13	\begin{proof}
14	The strategy passes the diagonal lines test with probability $1-\gamma$.
15	Therefore, it passes the $m$-restricted diagonal lines test with probability $1- \gamma\cdot m$.
16	This means that
17	\begin{equation*}
18	A^{u}_a \otimes I \simeq_{\gamma \cdot m} I \otimes L^{\ell}_{[f(u)=a]},
19	\end{equation*}
20	on average over a uniformly random $\bu \sim \F_q^{m}$ and a uniformly random line $\bell$ in $\F_q^m$
21	containing $\bu$.
22	By~\Cref{prop:simeq-to-approx}, this implies that
23	\begin{equation}\label{eq:point-diagonal-line-approx}
24	A^{u}_a \otimes I \approx_{2\cdot \gamma \cdot m} I \otimes L^{\ell}_{[f(u)=a]}. 
25	\end{equation}
26	
27	Let $\bu$ and $\bv$ be independent and uniformly random points in $\F_q^m$.
28	Let $\bell$ be a uniformly random line in $\F_q^m$ containing both points.
29	(If $\bu$ and $\bv$ are distinct, then $\bell$ is just the unique line that passes through both of them.
30	Otherwise, $\bu = \bv$, and $\bell$ is a uniformly random line passing through $\bu$.)
31	Then the marginal distribution on $\bu$ and $\bell$ is as in \Cref{eq:point-diagonal-line-approx},
32	as is the marginal distribution on $\bv$ and $\bell$.
33	As a result,
34	\begin{align*}
35	(A^{u}_a \cdot A^{v}_b) \otimes I
36	&\approx_{2\cdot \gamma \cdot m} A^{u}_a \otimes L^{\ell}_{[f(v)=b]} \tag{by \Cref{eq:point-diagonal-line-approx}}\\
37	&\approx_{2\cdot \gamma \cdot m} I \otimes (L^{\ell}_{[f(v)=b]} \cdot L^{\ell}_{[f'(u)=a]}) \tag{by \Cref{eq:point-diagonal-line-approx}}\\
38	&= I \otimes (L^{\ell}_{[f'(u)=a]} \cdot L^{\ell}_{[f(v)=b]}) \tag{because~$L$ is projective}\\
39	&\approx_{2\cdot \gamma \cdot m} A^{v}_b \otimes L^{\ell}_{[f'(u)=a]} \tag{by \Cref{eq:point-diagonal-line-approx}}\\
40	&\approx_{2\cdot \gamma \cdot m} (A^{v}_b \cdot A^{u}_a) \otimes I. \tag{by \Cref{eq:point-diagonal-line-approx}}
41	\end{align*}
42	The theorem now follows from
43	\Cref{prop:triangle-inequality-for-approx_delta}.
44	\end{proof}
