 27	\begin{proof}
 28		\leanok
 29		\uses{def:restricted-diagonal-lines-test, lem:good-strategy-characterization, prop:simeq-to-approx, prop:triangle-inequality-for-approx_delta}
 30		By Definition~\ref{def:restricted-diagonal-lines-test}, the strategy passes the $m$-restricted diagonal lines test with probability $1-\gamma m$. Hence
 31		\[
 32			A_a^u \otimes I \simeq_{\gamma m} I \otimes L^\ell_{[f(u)=a]}
 33		\]
 34		on average over uniformly random $u \sim \F_q^m$ and a uniformly random line $\ell$ in $\F_q^m$ containing $u$. By \ref{prop:simeq-to-approx},
 35		\begin{equation}\label{eq:point-diagonal-line-approx}
 36			A_a^u \otimes I \approx_{2\gamma m} I \otimes L^\ell_{[f(u)=a]}.
 37		\end{equation}
 38		Let $u$ and $v$ be independent uniformly random points in $\F_q^m$, and let $\ell$ be a uniformly random line containing both points. The marginal distribution on $(u,\ell)$ and on $(v,\ell)$ is the same as above, so
 39		\begin{align*}
 40			(A_a^u A_b^v) \ot I
 41			 & \approx_{2\gamma m} A_a^u \otimes L^\ell_{[f(v)=b]} \tag{by \ref{eq:point-diagonal-line-approx}}                           \\
 42			 & \approx_{2\gamma m} I \otimes \bigl(L^\ell_{[f(v)=b]} L^\ell_{[f(u)=a]}\bigr) \tag{by \ref{eq:point-diagonal-line-approx}} \\
