 57		Let $(\psi,A,B,L)$ be an $(\eps,\delta,\gamma)$-good symmetric strategy for the $(m+1,q,d)$ low individual degree test.
 58		Let $\{G^x\} \in \polysub{m}{q}{d}$ be a collection of projective sub-measurements indexed by $x \in \F_q$ with the following properties:
 59		\begin{enumerate}
 60			\item (Consistency with~$A$)\label{item:data-processed-consistency}
 61			      On average over $(u,x) \sim \F_q^{m+1}$,
 62			      \[
 63				      A_a^{u,x} \ot I \simeq_\zeta I \ot G^x_{[g(u)=a]}.
 64			      \]
 65			\item (Strong self-consistency)\label{item:data-processed-self-consistency}
 66			      On average over $x \sim \F_q$,
 67			      \[
 68				      G_g^x \ot I \approx_\zeta I \ot G_g^x.
 69			      \]
 70			\item (Boundedness)\label{item:data-processed-boundedness}
 71			      There exists a positive-semidefinite matrix $Z^x$ for each $x \in \F_q$ such that
 72			      \[
 73				      \E_x \bra{\psi} (I-G^x) \ot Z^x \ket{\psi} \le \zeta
 74			      \]
 75			      and for each $x \in \F_q$ and $g \in \polyfunc{m}{q}{d}$,
 76			      \[
 77				      Z^x \ge \left(\E_u A_{g(u)}^{u,x}\right).
 78			      \]
 79		\end{enumerate}
